    map['added_at'] = Variable<DateTime>(addedAt);
    if (!nullToAbsent || failureReason != null) {
      map['failure_reason'] = Variable<String>(failureReason);
    }
    map['crdt_overwrite'] = Variable<bool>(crdtOverwrite);
    return map;
